import type {Metadata} from "next";
import Link from "next/link";
import {ArrowLeft,Award,Check,CreditCard,Sparkles} from "lucide-react";
import {redirect} from "next/navigation";
import {openVendorBillingPortal,startVendorMembershipCheckout} from "./actions";
import {FOUNDING_MEMBER_OFFER,formatVendorPlanPrice,VENDOR_MEMBERSHIP_PLANS,getVendorPlanByCode,normalizeVendorPlanKey} from "@/src/domain/vendor-memberships/catalog";
import {getRoleHome} from "@/src/lib/auth/routing";
import {requireUser} from "@/src/lib/auth/session";
import {getFirebaseOrganizationMembership} from "@/src/lib/firebase/memberships";
import {isFirebaseOperationalBackend} from "@/src/lib/firebase/platform";
import {createSupabaseServerClient} from "@/src/lib/supabase/server";

export const metadata:Metadata={title:"Business Membership"};
export default async function VendorMembershipPage({searchParams}:{searchParams:Promise<{error?:string;checkout?:string;plan?:string}>}){
  const params=await searchParams;const requestedPlan=normalizeVendorPlanKey(params.plan??"");const user=await requireUser();const org=user.memberships.find(item=>item.organizationType==="vendor"&&["owner","admin","vendor"].includes(item.role));if(!org&&requestedPlan)redirect(`/onboarding?plan=${requestedPlan}`);if(!org)redirect(getRoleHome(user));
  let current:{status?:string;tier?:string;currentPeriodEndsAt?:{toDate():Date}|null;cancelAtPeriodEnd?:boolean;stripe?:{customerId?:string}|null}|null=null;
  if(isFirebaseOperationalBackend())current=await getFirebaseOrganizationMembership(org.organizationId);
  else{const supabase=await createSupabaseServerClient();const {data}=await supabase.from("vendor_memberships").select("status,current_period_ends_at,cancel_at_period_end,stripe_customer_id,vendor_membership_levels(code)").eq("vendor_organization_id",org.organizationId).order("created_at",{ascending:false}).limit(1).maybeSingle();const level=data?.vendor_membership_levels as unknown as {code:string}|null;current=data?{status:data.status,tier:level?.code,cancelAtPeriodEnd:data.cancel_at_period_end,stripe:data.stripe_customer_id?{customerId:data.stripe_customer_id}:null}:null;}
  const currentPlan=getVendorPlanByCode(current?.tier??"");
  return <div><Link href="/vendor" className="inline-flex items-center text-sm font-bold text-slate-500"><ArrowLeft className="mr-2 size-4"/>Vendor overview</Link>{params.error?<p role="alert" className="mt-5 rounded-xl bg-rose-50 p-4 text-sm font-semibold text-rose-800">{params.error==="already_active"?"This business already has a current membership.":"Membership checkout is temporarily unavailable."}</p>:null}<div className="mt-6 grid gap-5 lg:grid-cols-[1fr_auto]"><div><p className="text-xs font-black uppercase tracking-[.16em] text-emerald-700">Local business network</p><h1 className="mt-2 text-4xl font-semibold">Choose your membership.</h1><p className="mt-4 text-sm text-slate-500">Marketplace access requires verified billing, a complete profile, approval, and publication.</p></div><div className="rounded-2xl bg-slate-950 p-5 text-white"><p className="text-xs text-emerald-400">Current membership</p><p className="mt-2 text-xl font-bold">{currentPlan?.name??"No active plan"}</p><p className="mt-1 text-xs capitalize text-slate-400">{current?.status??"inactive"}</p>{current?.stripe?.customerId?<form action={openVendorBillingPortal}><button className="mt-4 rounded-full bg-white px-4 py-2 text-xs font-black text-slate-950"><CreditCard className="mr-2 inline size-4"/>Manage billing</button></form>:null}</div></div><section className="mt-8 grid gap-5 lg:grid-cols-3">{VENDOR_MEMBERSHIP_PLANS.map(plan=>{const active=currentPlan?.key===plan.key&&["active","trialing","past_due","complimentary","manually_granted"].includes(current?.status??"");const founding=plan.key==="founding_partner";return <article key={plan.key} className="flex flex-col rounded-3xl border border-slate-200 bg-white p-6"><span>{founding?<Award className="size-5 text-amber-700"/>:<Sparkles className="size-5 text-emerald-700"/>}</span><h2 className="mt-5 text-xl font-bold">{plan.name}</h2><p className="mt-3 text-3xl font-semibold">{formatVendorPlanPrice(plan)}</p><p className="mt-4 text-sm text-slate-500">{plan.description}</p><ul className="mt-6 space-y-2">{plan.features.map(feature=><li key={feature} className="flex gap-2 text-xs"><Check className="size-4 text-emerald-600"/>{feature}</li>)}</ul><div className="mt-auto pt-7">{active?<span className="font-bold text-emerald-700">Current plan</span>:founding?<Link href="/founders" className="inline-flex min-h-11 w-full items-center justify-center rounded-full bg-slate-950 text-xs font-black text-white">{FOUNDING_MEMBER_OFFER.cta}</Link>:<form action={startVendorMembershipCheckout}><input type="hidden" name="plan" value={plan.key}/><button className="min-h-11 w-full rounded-full bg-slate-950 text-xs font-black text-white">Join {plan.name}</button></form>}</div></article>})}</section></div>;
}
